UPDATE attachment
SET jhi_link = CONCAT('attachments/lecture/', SUBSTRING(jhi_link FROM 22))
WHERE jhi_link LIKE 'attachments/lectures/%';

UPDATE attachment
SET jhi_link = CONCAT('attachments/attachment-unit/', SUBSTRING(jhi_link FROM 36))
WHERE jhi_link LIKE 'attachments/attachment-video-units/%';

UPDATE attachment
SET student_version = CONCAT('attachments/attachment-unit/', SUBSTRING(student_version FROM 36))
WHERE student_version LIKE 'attachments/attachment-video-units/%';

UPDATE slide
SET slide_image_path = CONCAT('attachments/attachment-unit/', SUBSTRING(slide_image_path FROM 36))
WHERE slide_image_path LIKE 'attachments/attachment-video-units/%';
